-- Черновик всех уроков: фразы нужно сверить с носителем.
-- Вставить в SQL Editor целиком. Старые миграции повторно не запускать.
-- Повторный запуск не дублирует уже существующие задания.
-- Пройденный урок откроется с новых заданий. Опыт второй раз не начисляется.

drop function if exists public.seed_lesson_pack(text, text, jsonb);

create or replace function public.seed_lesson_pack(
  p_course text,
  p_lesson text,
  p_items jsonb
)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_lesson_id uuid;
  v_item jsonb;
  v_order integer;
  v_word_id uuid;
begin
  select lessons.id
  into v_lesson_id
  from public.lessons
  join public.courses on courses.id = lessons.course_id
  where courses.title = p_course
    and lessons.title = p_lesson;

  if v_lesson_id is null then
    raise exception 'Урок не найден: % / %', p_course, p_lesson;
  end if;

  for v_item in
    select value
    from jsonb_array_elements(p_items)
  loop
    v_order := (v_item ->> 'order')::integer;

    if exists (
      select 1
      from public.exercises
      where lesson_id = v_lesson_id
        and order_index = v_order
    ) then
      continue;
    end if;

    if v_item ->> 'type' = 'flashcard' then
      select vocabulary.id
      into v_word_id
      from public.vocabulary
      where vocabulary.kyrgyz_word = v_item ->> 'ky'
        and vocabulary.russian_translation = v_item ->> 'ru'
      order by vocabulary.created_at
      limit 1;

      if v_word_id is null then
        insert into public.vocabulary (
          kyrgyz_word,
          russian_translation,
          example_kyrgyz,
          example_russian
        )
        values (
          v_item ->> 'ky',
          v_item ->> 'ru',
          nullif(v_item ->> 'exKy', ''),
          nullif(v_item ->> 'exRu', '')
        )
        returning id into v_word_id;
      end if;

      insert into public.exercises (
        lesson_id,
        type,
        prompt,
        payload,
        accepted_answers,
        order_index,
        vocabulary_id
      )
      values (
        v_lesson_id,
        'flashcard',
        'Новое слово',
        jsonb_build_object(
          'kyrgyzWord', v_item ->> 'ky',
          'russianTranslation', v_item ->> 'ru',
          'exampleKyrgyz', coalesce(v_item ->> 'exKy', ''),
          'exampleRussian', coalesce(v_item ->> 'exRu', '')
        ),
        '{}',
        v_order,
        v_word_id
      );
    elsif v_item ->> 'type' = 'choice' then
      insert into public.exercises (
        lesson_id,
        type,
        prompt,
        payload,
        accepted_answers,
        explanation,
        order_index
      )
      values (
        v_lesson_id,
        'multiple_choice',
        v_item ->> 'prompt',
        jsonb_build_object(
          'prompt', v_item ->> 'prompt',
          'options', v_item -> 'options'
        ),
        array[v_item ->> 'answer'],
        v_item ->> 'explanation',
        v_order
      );
    elsif v_item ->> 'type' = 'sentence' then
      insert into public.exercises (
        lesson_id,
        type,
        prompt,
        payload,
        accepted_answers,
        explanation,
        order_index
      )
      values (
        v_lesson_id,
        'sentence_builder',
        'Соберите предложение',
        jsonb_build_object(
          'translation', v_item ->> 'translation',
          'tokens', v_item -> 'tokens',
          'distractors', v_item -> 'distractors'
        ),
        array[v_item ->> 'accepted'],
        v_item ->> 'explanation',
        v_order
      );
    else
      raise exception 'Неизвестный тип задания: %', v_item ->> 'type';
    end if;
  end loop;
end;
$fn$;


select public.seed_lesson_pack(
  'Знакомство',
  'Приветствие',
  $json$[{"order":8,"type":"flashcard","ky":"Кандайсың","ru":"Как дела","exKy":"Кандайсың?","exRu":"Как дела?"},{"order":9,"type":"flashcard","ky":"Жакшы","ru":"Хорошо","exKy":"Жакшы, рахмат.","exRu":"Хорошо, спасибо."},{"order":10,"type":"flashcard","ky":"Кош бол","ru":"До свидания","exKy":"Кош бол!","exRu":"До свидания!"},{"order":11,"type":"flashcard","ky":"Кечиресиз","ru":"Извините","exKy":"Кечиресиз.","exRu":"Извините."},{"order":12,"type":"choice","prompt":"Как переводится «Кандайсың»?","options":["Как дела","Спасибо","Здравствуйте","Хорошо"],"answer":"Как дела","explanation":"«Кандайсың» — неформальное «как дела»."},{"order":13,"type":"choice","prompt":"Как переводится «Жакшы»?","options":["Хорошо","Привет","До свидания","Извините"],"answer":"Хорошо","explanation":"«Жакшы» значит «хорошо»."},{"order":14,"type":"choice","prompt":"Как переводится «Кош бол»?","options":["До свидания","Спасибо","Привет","Пожалуйста"],"answer":"До свидания","explanation":"«Кош бол» — неформальное «до свидания»."},{"order":15,"type":"choice","prompt":"Как переводится «Кечиресиз»?","options":["Извините","Хорошо","Здравствуйте","Спасибо"],"answer":"Извините","explanation":"«Кечиресиз» значит «извините»."},{"order":16,"type":"sentence","translation":"Как дела?","tokens":["Сен","кандайсың"],"distractors":["рахмат","кош"],"accepted":"Сен кандайсың","explanation":"Сен кандайсың — «Как дела?»."},{"order":17,"type":"sentence","translation":"Хорошо, спасибо","tokens":["Жакшы","рахмат"],"distractors":["салам","сен"],"accepted":"Жакшы рахмат","explanation":"Жакшы, рахмат — «Хорошо, спасибо»."}]$json$::jsonb
);

