update public.user_progress as progress
set
  status = 'in_progress',
  completed_at = null,
  total_exercises = counts.total
from (
  select exercises.lesson_id, count(*)::integer as total
  from public.exercises
  group by exercises.lesson_id
) as counts
where progress.lesson_id = counts.lesson_id
  and progress.status = 'completed'
  and progress.current_exercise_index < counts.total
  and progress.lesson_id in (
    select lessons.id
    from public.lessons
    join public.courses on courses.id = lessons.course_id
    where courses.title in ('Знакомство', 'Моя семья', 'Мой рабочий день')
  );

drop function public.seed_lesson_pack(text, text, jsonb);
